/** Props every field control needs regardless of its value type. */
export interface FieldProps {
  /** Stable id associating the label with its control. */
  id: string
  /** Visible label. */
  label: string
  /** One-line explanation rendered under the control. */
  hint: string
  /**
   * Full sentence behind the visible hint, exposed as the paragraph's native
   * `title` so a card can shorten the line without losing the text. Omitted:
   * the paragraph carries no title attribute at all.
   */
  hintTitle?: string
  /** Draft text this control renders. */
  text: string
  /** True when the field holds a user-layer entry over the inherited value. */
  overridden: boolean
  /** True when the draft is not a value this field accepts. */
  invalid: boolean
  /** Copy for the overridden badge. */
  overriddenLabel: string
  /** Copy for the reset control. */
  resetLabel: string
  /** Copy shown in place of the hint while the draft is invalid. */
  invalidLabel: string
  /** Disables every control (read-only document, or an unavailable namespace). */
  disabled: boolean
  /** Take new draft text; the card writes it as the field's entry rule says. */
  onEdit: (text: string) => void
  /** Clear the field at once so it re-inherits the composition layer. */
  onReset: () => void
}

/**
 * A typed value field. Its draft is written after a pause in typing, at once on
 * Enter or when focus leaves, and Escape puts the stored value back. `numeric`
 * only hints the keypad: which drafts a field accepts is decided by its spec.
 * A field given a `range` also offers the coarse slider bubble: dragging fills
 * the draft live and releasing writes it.
 */
export function ValueField(props: FieldProps & {
  /** Hints a numeric keypad without narrowing what the control accepts. */
  numeric?: boolean
  /** Placeholder shown while the draft is empty. */
  placeholder?: string
  /** Bounds of a numeric field, for the coarse slider; the spec still judges every draft. */
  range?: { min: number, max: number, step: number }
}) {
  const apply = useContext(CardApply)
  // Enter and Escape settle the draft themselves and then leave the field, so
  // the blur they cause is that same settlement reaching the field's edge, not
  // a second write. Without this an Escape reported a discard and then a save,
  // which reads to a consumer as a write still waiting to happen.
  const settledByKey = useRef(false)
  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (apply === null || (event.key !== 'Enter' && event.key !== 'Escape')) return
    event.preventDefault()
    settledByKey.current = true
    if (event.key === 'Enter') apply.commit()
    else apply.revert()
    event.currentTarget.blur()
  }
  const input = (
    <input
      id={props.id}
      className={props.invalid ? css.inputInvalid : css.input}
      type="text"
      {...props.numeric === true ? { inputMode: 'numeric' as const } : {}}
      {...props.invalid ? { 'aria-invalid': true } : {}}
      value={props.text}
      placeholder={props.placeholder ?? ''}
      disabled={props.disabled}
      onChange={(event) => { props.onEdit(event.target.value) }}
      onKeyDown={onKeyDown}
      onFocus={() => { settledByKey.current = false }}
      onBlur={() => {
        if (settledByKey.current) {
          settledByKey.current = false
          return
        }
        apply?.commit()
      }}
    />
  )
  const { range } = props
  const typed = Number(props.text)
  return (
    <div className={css.field}>
      <div className={css.head}>
        <label className={css.label} htmlFor={props.id}>{props.label}</label>
        {props.overridden
          ? (
            <span className={css.badges}>
              <span className={css.badge}>{props.overriddenLabel}</span>
              <button
                type="button"
                className={css.reset}
                disabled={props.disabled}
                onClick={props.onReset}
              >
                {props.resetLabel}
              </button>
            </span>
          )
          : null}
      </div>
      {range === undefined
        ? input
        : (
          <RangeBubble
            min={range.min}
            max={range.max}
            step={range.step}
            value={props.text.trim() === '' || Number.isNaN(typed) ? range.min : typed}
            label={`${props.label} ${range.min}–${range.max}`}
            disabled={props.disabled}
            onInput={(value) => { props.onEdit(String(value)) }}
            onCommit={(value) => {
              props.onEdit(String(value))
              apply?.commit()
            }}
          >
            {input}
          </RangeBubble>
        )}
      <p className={props.invalid ? css.invalid : css.hint} title={props.hintTitle}>
        {props.invalid ? props.invalidLabel : props.hint}
      </p>
    </div>
  )
}

const NON_SKIN_BODY_MARKERS = new Set(['dshSkinCenter', 'dshSidebarCollapsed'])
// 检测使用使用皮肤，用了皮肤退回原生select样式，防止样式冲突。默认外观下使用优化后的select样式。
function isSkinActive(): boolean {
  const datasetList = Object.keys(document.body.dataset)
  const isActive = datasetList.some(key => key.startsWith('dsh') && !NON_SKIN_BODY_MARKERS.has(key))
  return isActive
}

interface SelectOption {
  value: string
  label: string
}

const SELECT_CLOSE_MS = 100

/**
 * The shared dual-mode select control. While an appearance skin is active it
 * renders the legacy native `<select>` untouched, so element-level skin
 * selectors keep working; under the default appearance it renders a
 * self-drawn `role="listbox"` popup whose open/close is transition-animated.
 * Cards reach it through BooleanField/ChoiceField; editors outside a card
 * (the side-card prefs) bind it directly through onEdit.
 * 双模式下拉框：皮肤激活时用原生 select，默认外观用自绘动画弹层。
 */
export function SelectField(props: {
  id: string
  options: ReadonlyArray<SelectOption>
  value: string
  disabled: boolean
  invalid: boolean
  onEdit: (text: string) => void
}) {
  const { id, options, value } = props
  const [open, setOpen] = useState(false)
  const [closing, setClosing] = useState(false)
  const [phase, setPhase] = useState<'initial' | 'open'>('initial')
  const [activeIndex, setActiveIndex] = useState(0)
  const closeTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  const wrapRef = useRef<HTMLDivElement | null>(null)
  const popupRef = useRef<HTMLDivElement | null>(null)

  const currentIndex = () => {
    const index = options.findIndex(option => option.value === value)
    return index >= 0 ? index : 0
  }

  const close = useCallback(() => {
    if (closeTimer.current !== undefined) clearTimeout(closeTimer.current)
    setClosing(true)
    closeTimer.current = setTimeout(() => {
      setClosing(false)
      setOpen(false)
    }, SELECT_CLOSE_MS)
  }, [])

  const openPopup = () => {
    if (closeTimer.current !== undefined) clearTimeout(closeTimer.current)
    setActiveIndex(currentIndex())
    setPhase('initial')
    setClosing(false)
    setOpen(true)
  }

  const commit = (index: number) => {
    const option = options[index]
    if (option) props.onEdit(option.value)
    close()
  }

  const onTriggerClick = () => {
    if (props.disabled) return
    if (open && !closing) close()
    else openPopup()
  }

  const onKeyDown = (event: KeyboardEvent<HTMLButtonElement>) => {
    if (props.disabled) return
    const count = options.length
    switch (event.key) {
      case 'ArrowDown':
      case 'ArrowUp':
      case 'Enter':
      case ' ':
        event.preventDefault()
        if (!open) {
          openPopup()
        } else if (!closing) {
          if (event.key === 'ArrowDown') setActiveIndex(index => (index + 1) % count)
          else if (event.key === 'ArrowUp') setActiveIndex(index => (index - 1 + count) % count)
          else commit(activeIndex)
        }
        break
      case 'Escape':
        if (open) {
          event.preventDefault()
          event.stopPropagation()
          close()
        }
        break
      case 'Tab':
        if (open) close()
        break
    }
  }

  useEffect(() => () => {
    if (closeTimer.current !== undefined) clearTimeout(closeTimer.current)
  }, [])
  useLayoutEffect(() => {
    if (open && !closing && phase === 'initial') {
      void popupRef.current?.offsetHeight
      setPhase('open')
    }
  }, [open, closing, phase])

  useEffect(() => {
    if (!open) return
    const onPointerDown = (event: PointerEvent) => {
      const target = event.target
      if (target instanceof Node && !wrapRef.current?.contains(target)) close()
    }
    document.addEventListener('pointerdown', onPointerDown)
    return () => document.removeEventListener('pointerdown', onPointerDown)
  }, [open, close])

  useEffect(() => {
    if (props.disabled && open) close()
  }, [props.disabled, open, close])

  // 使用了皮肤则退回原生select样式防止样式冲突。
  if (isSkinActive()) {
    return (
      <select
        id={id}
        className={css.select}
        value={value}
        disabled={props.disabled}
        onChange={(event) => { props.onEdit(event.target.value) }}
      >
        {options.map(option => (
          <option key={option.value} value={option.value}>{option.label}</option>
        ))}
      </select>
    )
  }

  const label = options.find(option => option.value === value)?.label ?? ''
  const popupClass = closing
    ? `${css.selectPopup} ${css.selectPopupClose}`
    : phase === 'open'
      ? `${css.selectPopup} ${css.selectPopupOpen}`
      : css.selectPopup
  return (
    <div className={css.selectWrap} ref={wrapRef}>
      <button
        type="button"
        id={id}
        className={`${css.select} ${css.selectButton}`}
        disabled={props.disabled}
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-activedescendant={open ? `${id}-o${activeIndex}` : undefined}
        aria-invalid={props.invalid || undefined}
        onClick={onTriggerClick}
        onKeyDown={onKeyDown}
      >
        <span className={css.selectLabel}>{label}</span>
        <svg
          width="14"
          height="14"
          viewBox="0 0 14 14"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
          className={open ? `${css.selectChevron} ${css.selectChevronOpen}` : css.selectChevron}
          aria-hidden="true"
        >
          <path
            d="M11.8486 5.5L11.4238 5.92383L8.69727 8.65137C8.44157 8.90706 8.21562 9.13382 8.01172 9.29785C7.79912 9.46883 7.55595 9.61756 7.25 9.66602C7.08435 9.69222 6.91565 9.69222 6.75 9.66602C6.44405 9.61756 6.20088 9.46883 5.98828 9.29785C5.78438 9.13382 5.55843 8.90706 5.30273 8.65137L2.57617 5.92383L2.15137 5.5L3 4.65137L3.42383 5.07617L6.15137 7.80273C6.42595 8.07732 6.59876 8.24849 6.74023 8.3623C6.87291 8.46904 6.92272 8.47813 6.9375 8.48047C6.97895 8.48703 7.02105 8.48703 7.0625 8.48047C7.07728 8.47813 7.12709 8.46904 7.25977 8.3623C7.40124 8.24849 7.57405 8.07732 7.84863 7.80273L10.5762 5.07617L11 4.65137L11.8486 5.5Z"
            fill="currentColor"
          />
        </svg>
      </button>
      {open
        ? (
          <div className={popupClass} role="listbox" ref={popupRef}>
            {options.map((option, index) => (
              <div
                key={option.value}
                id={`${id}-o${index}`}
                role="option"
                aria-selected={option.value === value}
                className={`${css.selectOption}${option.value === value ? ` ${css.selectOptionSelected}` : ''}${index === activeIndex && !closing ? ` ${css.selectOptionActive}` : ''}`}
                onClick={() => { commit(index) }}
              >
                {option.label}
              </div>
            ))}
          </div>
        )
        : null}
    </div>
  )
}

/**
 * A visible segmented group for a small set of mutually exclusive values.
 * Every option stays on screen, so inherit/on/off and short enum fields take
 * one click without opening a popup. The pressed option carries the group's
 * sliding highlight and `aria-pressed`; the group takes the field label as its
 * accessible name.
 */
export function SegmentField(props: {
  id: string
  label: string
  options: ReadonlyArray<SelectOption>
  value: string
  disabled: boolean
  invalid: boolean
  onEdit: (text: string) => void
}) {
  return (
    <SegmentGroup
      id={props.id}
      role="group"
      aria-label={props.label}
      aria-invalid={props.invalid || undefined}
    >
      {props.options.map((option, index) => {
        const active = option.value === props.value
        return (
          <button
            key={option.value}
            type="button"
            className={css.segment}
            aria-pressed={active}
            disabled={props.disabled}
            data-active={active ? '' : undefined}
            data-segment-index={index}
            onClick={() => {
              if (!active) props.onEdit(option.value)
            }}
          >
            {option.label}
          </button>
        )
      })}
    </SegmentGroup>
  )
}

/** How a small single-choice field presents its options. */
export type FieldPresentation = 'select' | 'segment'

/** A boolean field: 继承 / 开 / 关. */
export function BooleanField(props: FieldProps & {
  /** Copy for the inherit option. */
  inheritLabel: string
  /** Copy for the on option. */
  onLabel: string
  /** Copy for the off option. */
  offLabel: string
  /** Defaults to the visible segments: the three answers always fit on one row. */
  presentation?: FieldPresentation
}) {
  const segmented = props.presentation !== 'select'
  return (
    <div className={css.field}>
      <div className={css.head}>
        {segmented
          ? <span className={css.label}>{props.label}</span>
          : <label className={css.label} htmlFor={props.id}>{props.label}</label>}
        {props.overridden
          ? (
            <span className={css.badges}>
              <span className={css.badge}>{props.overriddenLabel}</span>
              <button
                type="button"
                className={css.reset}
                disabled={props.disabled}
                onClick={props.onReset}
              >
                {props.resetLabel}
              </button>
            </span>
          )
          : null}
      </div>
      {segmented
        ? (
          <SegmentField
            id={props.id}
            label={props.label}
            options={[
              { value: '', label: props.inheritLabel },
              { value: 'true', label: props.onLabel },
              { value: 'false', label: props.offLabel },
            ]}
            value={props.text}
            disabled={props.disabled}
            invalid={props.invalid}
            onEdit={props.onEdit}
          />
        )
        : (
          <SelectField
            id={props.id}
            options={[
              { value: '', label: props.inheritLabel },
              { value: 'true', label: props.onLabel },
              { value: 'false', label: props.offLabel },
            ]}
            value={props.text}
            disabled={props.disabled}
            invalid={props.invalid}
            onEdit={props.onEdit}
          />
        )}
      <p className={css.hint} title={props.hintTitle}>{props.hint}</p>
    </div>
  )
}

/** An enumerated field, selecting or segmenting its small choice set. */
export function ChoiceField(props: FieldProps & {
  /** Copy for the inherit option (draft text is the empty string). */
  inheritLabel: string
  /** Choices rendered in order; `value` is the draft/stored text. */
  choices: ReadonlyArray<{ value: string; label: string }>
  /**
   * Visible segmented options for a short fixed set; defaults to the compact
   * select, which also suits a list whose length follows the deployment.
   */
  presentation?: FieldPresentation
}) {
  const segmented = props.presentation === 'segment'
  const options = [{ value: '', label: props.inheritLabel }, ...props.choices]
  return (
    <div className={css.field}>
      <div className={css.head}>
        {segmented
          ? <span className={css.label}>{props.label}</span>
          : <label className={css.label} htmlFor={props.id}>{props.label}</label>}
        {props.overridden
          ? (
            <span className={css.badges}>
              <span className={css.badge}>{props.overriddenLabel}</span>
              <button
                type="button"
                className={css.reset}
                disabled={props.disabled}
                onClick={props.onReset}
              >
                {props.resetLabel}
              </button>
            </span>
          )
          : null}
      </div>
      {segmented
        ? (
          <SegmentField
            id={props.id}
            label={props.label}
            options={options}
            value={props.text}
            disabled={props.disabled}
            invalid={props.invalid}
            onEdit={props.onEdit}
          />
        )
        : (
          <SelectField
            id={props.id}
            options={options}
            value={props.text}
            disabled={props.disabled}
            invalid={props.invalid}
            onEdit={props.onEdit}
          />
        )}
      <p className={props.invalid ? css.invalid : css.hint} title={props.hintTitle}>
        {props.invalid ? props.invalidLabel : props.hint}
      </p>
    </div>
  )
}

/**
 * A boolean toggle drawn as a switch track, for a setting that is only on or
 * off and applies on flip. It is a real button with
 * `role="switch"` and `aria-checked`, so keyboard and assistive activation
 * arrive as a click and the state is announced instead of inferred from a
 * checkbox tick.
 *
 * The thumb bounces across only once the reader has pressed this switch: the
 * press writes the mark that arms the bounce, so a page opening, a TAB
 * switching back or a value arriving from elsewhere draws every thumb at rest.
 */
export function ToggleSwitch(props: {
  /** Id of the element naming the switch (the card's title). */
  labelledBy?: string
  /** Accessible name when no element labels it. */
  ariaLabel?: string
  /** Current state. */
  checked: boolean
  /** Disables the switch while a write is in flight or the Host refuses writes. */
  disabled?: boolean
  /** Called with the requested next state. */
  onChange: (next: boolean) => void
}) {
  const [moved, setMoved] = useState(false)
  return (
    <button
      type="button"
      className={css.toggle}
      role="switch"
      aria-checked={props.checked}
      aria-labelledby={props.labelledBy}
      aria-label={props.labelledBy === undefined ? props.ariaLabel : undefined}
      disabled={props.disabled}
      data-moved={moved ? '' : undefined}
      onClick={() => {
        setMoved(true)
        props.onChange(!props.checked)
      }}
    >
      <span className={css.toggleTrack}><span className={css.toggleThumb} /></span>
    </button>
  )
}
